# 3) per-res summary
rows = []
for res in sorted(set(vd['res'])):
    g = vd[vd['res'] == res]
    def M(c): return round(float(g[c].mean()), 4)
    def S(c): return round(float(g[c].std()), 4)
    rows.append({'res': res, 'ari_mean': M('ari'), 'ari_std': S('ari'), 'nmi_mean': M('nmi'), 'nmi_std': S('nmi'),
                 'sil_mean': M('silhouette'), 'sil_std': S('silhouette'), 'coh_mean': M('coherence'), 'coh_std': S('coherence'),
                 'sc_mean': M('sc_overlap_post'), 'sc_std': S('sc_overlap_post'), 'sc_5of5': int((g['sc_overlap_post'] == 1.0).sum()),
                 'drg_mean': M('drg_overlap_post'), 'drg_std': S('drg_overlap_post'), 'drg_5of5': int((g['drg_overlap_post'] >= 0.9).sum()),
                 'n_split': int(g['sc_split_triggered'].sum())})
sm = pd.DataFrame(rows)
sm.to_csv('F:/BGI/task3/spateo-release-main/results/method2_weighted_union_final/tables/overall_metrics.csv', index=False, encoding='utf-8-sig')

summary = {'chosen_alpha': 1.5, 'accepted': True, 'per_res': rows}
json.dump(summary, open('F:/tmp/m2_final_summary.json','w'), indent=1)

res1 = sm[sm['res'] == 1.0].iloc[0]
sc_all_stable = bool((sm['sc_5of5'] == 5).all() and (sm['sc_mean'] == 1.0).all() and (sm['sc_std'] == 0.0).all())
drg_res1_stable = bool(res1['drg_5of5'] == 5)

print(json.dumps({'chosen_alpha': 1.5, 'accepted': True,
  'sc_all_stable': sc_all_stable, 'sc_5of5_every_res': bool((sm['sc_5of5'] == 5).all()),
  'sc_mean_res1': res1['sc_mean'], 'sc_std_res1': res1['sc_std'],
  'drg_5of5_res1': drg_res1_stable, 'drg_mean_res1': res1['drg_mean'], 'drg_std_res1': res1['drg_std'],
  'ari_res1_mean': res1['ari_mean'], 'ari_res1_std': res1['ari_std'], 'nmi_res1_mean': res1['nmi_mean'],
  'coh_res1_mean': res1['coh_mean'], 'sil_res1_mean': res1['sil_mean'],
  'csv_scan': 'F:/BGI/task3/spateo-release-main/results/analysis/method2_final_alpha_scan.csv',
  'csv_verify': 'F:/BGI/task3/spateo-release-main/results/analysis/method2_final_verify.csv',
  'overall_metrics': 'F:/BGI/task3/spateo-release-main/results/method2_weighted_union_final/tables/overall_metrics.csv',
  'verdict': ('SC deterministic split 100% stable across 5 seeds at every resolution (mean=1.0, std=0). DRG stable 5/5 at res=1.0.') if (sc_all_stable and drg_res1_stable) else ('SC stable, but DRG at res=1.0 NOT 5/5 - report honestly.')}))
